static PAFile pj_stdio_fopen(projCtx ctx, const char *filename,
                             const char *access);
static size_t pj_stdio_fread(void *buffer, size_t size, size_t nmemb,
                             PAFile file);
static int pj_stdio_fseek(PAFile file, long offset, int whence);
static long pj_stdio_ftell(PAFile file);
static void pj_stdio_fclose(PAFile file);

static projFileAPI default_fileapi = {
    pj_stdio_fopen,
    pj_stdio_fread,
    pj_stdio_fseek,
    pj_stdio_ftell,
    pj_stdio_fclose
};

typedef struct {
    projCtx ctx;
    FILE *fp;
} stdio_pafile;

/************************************************************************/
/*                       pj_get_default_fileapi()                       */
/************************************************************************/

projFileAPI *pj_get_default_fileapi(void)
{
    return &default_fileapi;
}

/************************************************************************/
/*                           pj_stdio_fopen()                           */
/************************************************************************/

static PAFile pj_stdio_fopen(projCtx ctx, const char *filename,
                             const char *access)
{
    stdio_pafile *pafile;
    FILE *fp;

    fp = fopen(filename, access);
    if (fp == NULL)
    {
        return NULL;
    }

    pafile = (stdio_pafile *) malloc(sizeof(stdio_pafile));
    pafile->fp = fp;
    pafile->ctx = ctx;
    return (PAFile) pafile;
}

/************************************************************************/
/*                           pj_stdio_fread()                           */
/************************************************************************/

static size_t pj_stdio_fread(void *buffer, size_t size, size_t nmemb,
                             PAFile file)
{
    stdio_pafile *pafile = (stdio_pafile *) file;
    return fread(buffer, size, nmemb, pafile->fp);
}

/************************************************************************/
/*                           pj_stdio_fseek()                           */
/************************************************************************/
static int pj_stdio_fseek(PAFile file, long offset, int whence)
{
    stdio_pafile *pafile = (stdio_pafile *) file;
    return fseek(pafile->fp, offset, whence);
}

/************************************************************************/
/*                           pj_stdio_ftell()                           */
/************************************************************************/
static long pj_stdio_ftell(PAFile file)
{
    stdio_pafile *pafile = (stdio_pafile *) file;
    return ftell(pafile->fp);
}

/************************************************************************/
/*                          pj_stdio_fclose()                           */
/************************************************************************/
static void pj_stdio_fclose(PAFile file)
{
    stdio_pafile *pafile = (stdio_pafile *) file;
    fclose(pafile->fp);
    free(pafile);
}

/************************************************************************/
/*                            pj_ctx_fopen()                            */
/*                                                                      */
/*      Open a file using the provided file io hooks.                   */
/************************************************************************/

PAFile pj_ctx_fopen(projCtx ctx, const char *filename, const char *access)
{
    return ctx->fileapi->FOpen(ctx, filename, access);
}

/************************************************************************/
/*                            pj_ctx_fread()                            */
/************************************************************************/
size_t pj_ctx_fread(projCtx ctx, void *buffer, size_t size, size_t nmemb, PAFile file)
{
    return ctx->fileapi->FRead(buffer, size, nmemb, file);
}

/************************************************************************/
/*                            pj_ctx_fseek()                            */
/************************************************************************/
int    pj_ctx_fseek(projCtx ctx, PAFile file, long offset, int whence)
{
    return ctx->fileapi->FSeek(file, offset, whence);
}

/************************************************************************/
/*                            pj_ctx_ftell()                            */
/************************************************************************/
long   pj_ctx_ftell(projCtx ctx, PAFile file)
{
    return ctx->fileapi->FTell(file);
}

/************************************************************************/
/*                           pj_ctx_fclose()                            */
/************************************************************************/
void   pj_ctx_fclose(projCtx ctx, PAFile file)
{
    ctx->fileapi->FClose(file);
}

/************************************************************************/
/*                            pj_ctx_fgets()                            */
/*                                                                      */
/*      A not very optimal implementation of fgets on top of            */
/*      fread().  If we end up using this a lot more care should be     */
/*      taken.                                                          */
/************************************************************************/

char *pj_ctx_fgets(projCtx ctx, char *line, int size, PAFile file)
{
    long start = pj_ctx_ftell(ctx, file);
    size_t bytes_read;
    int i;

    line[size-1] = '\0';
    bytes_read = pj_ctx_fread(ctx, line, 1, size-1, file);
    if(bytes_read == 0)
        return NULL;
    if(bytes_read < (size_t)size)
    {
        line[bytes_read] = '\0';
    }

    for( i = 0; i < size-2; i++)
    {
        if (line[i] == '\n')
        {
            line[i+1] = '\0';
            pj_ctx_fseek(ctx, file, start + i + 1, SEEK_SET);
            break;
        }
    }
    return line;
}
--- src-vul/proj.4/src/pj_fwd.c
/* general forward projection */
#define PJ_LIB__
#include <proj.h>
#include <projects.h>
# define EPS 1.0e-12
        XY /* forward projection entry */
pj_fwd(LP lp, PJ *P) {
        XY xy;
    XY err;
    double t;
    int last_errno;

    /* cannot const-initialize this due to MSVC's broken (non const) HUGE_VAL */
    err.x = err.y = HUGE_VAL;

    if (0==P->fwd)
        return err;
    last_errno = proj_errno_reset (P);

    /* Check input coordinates if angular */
    if ((P->left==PJ_IO_UNITS_CLASSIC)||(P->left==PJ_IO_UNITS_RADIANS)) {

        /* check for forward and latitude or longitude overange */
        t = fabs(lp.phi)-M_HALFPI;
        if (t > EPS || fabs(lp.lam) > 10.) {
            pj_ctx_set_errno( P->ctx, -14);
            return err;
        }

        /* Clamp latitude to -90..90 degree range */
        if (fabs(t) <= EPS)
            lp.phi = lp.phi < 0. ? -M_HALFPI : M_HALFPI;
        else if (P->geoc)   /* Maybe redundant and never used. */
            lp.phi = atan(P->rone_es * tan(lp.phi));
        lp.lam -= P->lam0;    /* compute del lp.lam */
        if (!P->over)
            lp.lam = adjlon(lp.lam); /* adjust del longitude */
    }

    /* Do the transformation */
    xy = (*P->fwd)(lp, P);
    if ( proj_errno (P) )
        return err;

    /* Classic proj.4 functions return plane coordinates in units of the semimajor axis */
    if (P->right==PJ_IO_UNITS_CLASSIC) {
        xy.x *= P->a;
        xy.y *= P->a;
    }

    /* Handle false eastings/northings and non-metric linear units */
    xy.x = P->fr_meter * (xy.x + P->x0);
    xy.y = P->fr_meter * (xy.y + P->y0);
    /* z is not scaled since this is handled by vto_meter outside */

    proj_errno_restore (P, last_errno);
    return xy;
}
--- src-vul/proj.4/src/pj_fwd3d.c
#define PJ_LIB__
#include <proj.h>
#include <projects.h>
#include <errno.h>
# define EPS 1.0e-12

/* 3D Forward transformation */

XYZ pj_fwd3d(LPZ lpz, PJ *P) {
    XYZ xyz;
    XYZ err;
    double t;
    int last_errno;

    /* cannot const-initialize this due to MSVC's broken (non const) HUGE_VAL */
    err.x = err.y = err.z = HUGE_VAL;

    if (0==P->fwd3d)
        return err;

    last_errno = proj_errno_reset(P);

    /* Check input coordinates if angular */
    if ((P->left==PJ_IO_UNITS_CLASSIC)||(P->left==PJ_IO_UNITS_RADIANS)) {

        /* check for forward and latitude or longitude overange */
        t = fabs(lpz.phi)-M_HALFPI;
        if (t > EPS || fabs(lpz.lam) > 10.) {
            pj_ctx_set_errno( P->ctx, -14);
            return err;
        }

        /* Clamp latitude to -90..90 degree range */
        if (fabs(t) <= EPS)
            lpz.phi = lpz.phi < 0. ? -M_HALFPI : M_HALFPI;
        else if (P->geoc)   /* Maybe redundant and never used. */
            lpz.phi = atan(P->rone_es * tan(lpz.phi));
        lpz.lam -= P->lam0;    /* compute del lp.lam */
        if (!P->over)
            lpz.lam = adjlon(lpz.lam); /* adjust del longitude */
    }

    /* Do the transformation */
    xyz = (*P->fwd3d)(lpz, P);
    if ( P->ctx->last_errno )
        return err;

    /* Classic proj.4 functions return plane coordinates in units of the semimajor axis */
    if (P->right==PJ_IO_UNITS_CLASSIC) {
        xyz.x *= P->a;
        xyz.y *= P->a;
    }

    /* Handle false eastings/northings and non-metric linear units */
    xyz.x = P->fr_meter * (xyz.x + P->x0);
    xyz.y = P->fr_meter * (xyz.y + P->y0);
    /* z is not scaled since this is handled by vto_meter outside */

    proj_errno_restore (P, last_errno);
    return xyz;
}
