/* very loosely based upon DMA code by Bradford W. Drew */
#define PJ_LIB__
#include <projects.h>

PROJ_HEAD(lonlat, "Lat/long (Geodetic)")  "\n\t";
PROJ_HEAD(latlon, "Lat/long (Geodetic alias)")  "\n\t";
PROJ_HEAD(latlong, "Lat/long (Geodetic alias)")  "\n\t";
PROJ_HEAD(longlat, "Lat/long (Geodetic alias)")  "\n\t";


 static XY forward(LP lp, PJ *P) {
    XY xy = {0.0,0.0};
    xy.x = lp.lam / P->a;
    xy.y = lp.phi / P->a;
    return xy;
}


static LP inverse(XY xy, PJ *P) {
    LP lp = {0.0,0.0};
    lp.phi = xy.y * P->a;
    lp.lam = xy.x * P->a;
    return lp;
}


static void *freeup_new (PJ *P) {
    if (0==P)
        return 0;

    return pj_dealloc(P);
}

static void freeup (PJ *P) {
    freeup_new (P);
    return;
}


PJ *PROJECTION(latlong) {
    P->is_latlong = 1;
    P->x0 = 0.0;
    P->y0 = 0.0;
    P->inv = inverse;
    P->fwd = forward;

    return P;
}


PJ *PROJECTION(longlat) {
    P->is_latlong = 1;
    P->x0 = 0.0;
    P->y0 = 0.0;
    P->inv = inverse;
    P->fwd = forward;

    return P;
}


PJ *PROJECTION(latlon) {
    P->is_latlong = 1;
    P->x0 = 0.0;
    P->y0 = 0.0;
    P->inv = inverse;
    P->fwd = forward;

    return P;
}


PJ *PROJECTION(lonlat) {
    P->is_latlong = 1;
    P->x0 = 0.0;
    P->y0 = 0.0;
    P->inv = inverse; P->fwd = forward;

    return P;
}


