/* print projection's list of parameters */
#include <projects.h>
#include <stdio.h>
#include <string.h>
#define LINE_LEN 72
        static int
pr_list(PJ *P, int not_used) {
        paralist *t;
        int l, n = 1, flag = 0;

        (void)putchar('#');
        for (t = P->params; t; t = t->next)
           if ((!not_used && t->used) || (not_used && !t->used)) {
                l = (int)strlen(t->param) + 1;
                if (n + l > LINE_LEN) {
                        (void)fputs("\n#", stdout);
                        n = 2;
                }
                (void)putchar(' ');
                if (*(t->param) != '+')
                        (void)putchar('+');
                (void)fputs(t->param, stdout);
                n += l;
           } else
                flag = 1;
        if (n > 1)
           (void)putchar('\n');
        return flag;
}
        void /* print link list of projection parameters */
pj_pr_list(PJ *P) {
        char const *s;

        (void)putchar('#');
        for (s = P->descr; *s ; ++s) {
           (void)putchar(*s);
           if (*s == '\n')
                (void)putchar('#');
        }
        (void)putchar('\n');
        if (pr_list(P, 0)) {
           (void)fputs("#--- following specified but NOT used\n", stdout);
           (void)pr_list(P, 1);
        }
}

/************************************************************************/
/*                             pj_get_def()                             */
/*                                                                      */
/*      Returns the PROJ.4 command string that would produce this       */
/*      definition expanded as much as possible.  For instance,         */
/*      +init= calls and +datum= definitions would be expanded.         */
/************************************************************************/

char *pj_get_def( PJ *P, int options )

{
    paralist *t;
    int l;
    char *definition;
    size_t def_max = 10;
    (void) options;

    definition = (char *) pj_malloc(def_max);
    definition[0] = '\0';

    for (t = P->params; t; t = t->next)
    {
        /* skip unused parameters ... mostly appended defaults and stuff */
        if (!t->used)
            continue;

        /* grow the resulting string if needed */
        l = (int)strlen(t->param) + 1;
        if( strlen(definition) + l + 5 > def_max )
        {
            char *def2;

            def_max = def_max * 2 + l + 5;
            def2 = (char *) pj_malloc(def_max);
            strcpy( def2, definition );
            pj_dalloc( definition );
            definition = def2;
        }

        /* append this parameter */
        strcat( definition, " +" );
        strcat( definition, t->param );
    }

    return definition;
}
--- src-vul/proj.4/src/pj_qsfn.c
/* determine small q */
#include <math.h>
#include <projects.h>

# define EPSILON 1.0e-7

double pj_qsfn(double sinphi, double e, double one_es) {
    double con, div1, div2;

    if (e >= EPSILON) {
        con = e * sinphi;
        div1 = 1.0 - con * con;
        div2 = 1.0 + con;

        /* avoid zero division, fail gracefully */
        if (div1 == 0.0 || div2 == 0.0)
            return HUGE_VAL;

        return (one_es * (sinphi / div1 - (.5 / e) * log ((1. - con) / div2 )));
    } else
        return (sinphi + sinphi);
}
